                i = str-1;
                str = -1;
            }
        }
        String arr [] = skobki.split("_");
        int count = 0;

        for (int i = 0; i < arr.length; i++)
            if (!arr[i].equals("")) count++;
         arr  = s.split("_");
        int max = 0;
        for (int i = 0; i < arr.length; i++)
            if (arr[i].length() > max) max = arr[i].length();
